{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Use mean pairwise BPR over existing valid positions and sampled negatives for all four datasets. Directly optimizing positive-versus-negative ordering may improve HR@10. Preserve the SASRec architecture, scoring, sampling, optimizer, parameter regularization, training settings, and single-model prediction.",
      "edits": [
        {
          "find": "  - Official BCEWithLogits loss on positive and negative sequence logits",
          "replace": "  - Mean pairwise BPR loss on valid positive and negative sequence logits"
        },
        {
          "find": "    bce_criterion = nn.BCEWithLogitsLoss(reduction=\"none\")\n    observed_counts = item_counts[item_counts > 0]\n    median_count = float(np.median(observed_counts)) if observed_counts.size else 1.0\n    target_loss_weights = torch.clamp(\n        (median_count / model.item_counts.clamp_min(1.0)).pow(0.25),\n        min=0.5, max=2.0,\n    )\n    target_loss_weights[0] = 0.0\n",
          "replace": "    ranking_criterion = nn.Softplus()\n"
        },
        {
          "find": "            pos_labels = torch.ones_like(positive_logits)\n            neg_labels = torch.zeros_like(negative_logits)\n            baseline_loss = (\n                bce_criterion(positive_logits, pos_labels)\n                + bce_criterion(negative_logits, neg_labels)\n            )\n            ranking_loss = torch.nn.functional.softplus(negative_logits - positive_logits)\n            weights = target_loss_weights[pos_t[indices]]\n            weights = weights / weights.mean().clamp_min(1e-8)\n            loss = (weights * (0.75 * baseline_loss + 0.25 * ranking_loss)).mean()",
          "replace": "            loss = ranking_criterion(negative_logits - positive_logits).mean()"
        }
      ]
    }
  ],
  "change_summary": "Replace the weighted BCE/BPR mixture with unweighted mean pairwise BPR across all four datasets. Architecture, checkpoints, predictor, routing, seeds, and epoch cap remain unchanged."
}
